(function(){
'use strict';
const $=id=>document.getElementById(id),E=GuardianEngine,model=new E.Controller(),canvas=$('stage'),ctx=canvas.getContext('2d'),sheetCanvas=$('sheet');
const names={south:'Sul',west:'Oeste',east:'Leste',north:'Norte'};const cfg={zoom:1.4,hair:true,grid:false,bounds:false,plain:false};let renderer,hitCount=0,held=false,last=0,currentSheet='',raf=0;let effects=[];const dummy={x:720,y:325,shake:0};
function notify(text){$('notice').textContent=text;}
function selectAction(action){if(!model.choose(action)){if(model.lifeState!=='alive')notify('Personagem morto. Use Reviver para continuar.');$('action').value=model.manual;return false;}$('action').value=action;currentSheet='';return true;}
function attack(dir=model.dir){if(model.lifeState!=='alive'){held=false;notify('Reviva o personagem antes de atacar.');return false;}if(model.manual!=='auto')selectAction('auto');model.attack(dir);}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function blobOf(c){return new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('Não foi possível gerar o PNG.')),'image/png'));}
function registeredMetadata(){const sheets={};for(const [name,data] of Object.entries(GuardianData.atlas.sheets)){const cell=data.cellExport||192;sheets[name]={file:'guardian-'+name+'-registrado.png',columns:data.columns,rows:4,cellWidth:cell,cellHeight:cell,anchorX:cell/2,anchorY:cell*.88,frames:data.columns*4,fps:E.ACTIONS[name].fps};}return {version:'1.0-morte',directions:E.DIRECTIONS,sheets,idle:{blinkPeriod:3.8,blinkSequence:[0,1,2,1,3,0],closedDuration:.1},death:{fps:8,frames:6,loop:false,holdLast:true,blocksMovement:true,blocksAttack:true},hair:{type:'Deslocamento suave de faixas da coroa no renderizador',amplitude:.95,period:2.03},notes:['Quatro orientações e 112 quadros base (88 originais e 24 de morte).','Repouso não usa quadros uniformes: piscada breve após 3,48 segundos.','As folhas registradas já têm o espelhamento oeste aplicado; não repetir flip.','Vento no cabelo e respiração são efeitos do renderizador, não quadros adicionais.','Arte de teste com lateralidade da espada a revisar antes da integração.']};}
function makeSheet(action){const data=GuardianData.atlas.sheets[action],out=document.createElement('canvas');const cell=data.cellExport||192;out.width=data.columns*cell;out.height=4*cell;renderer.sheet(out.getContext('2d'),action);return out;}
function crc32(data){let crc=0xffffffff;for(let i=0;i<data.length;i++){crc^=data[i];for(let b=0;b<8;b++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return (crc^0xffffffff)>>>0;}
function zipStore(entries){const local=[],central=[];let offset=0;const enc=new TextEncoder();function bytes(size){const u=new Uint8Array(size);return [u,new DataView(u.buffer)];}
for(const entry of entries){const name=enc.encode(entry.name),data=entry.data,crc=crc32(data);let [h,v]=bytes(30+name.length);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);h.set(name,30);local.push(h,data);
let [c,w]=bytes(46+name.length);w.setUint32(0,0x02014b50,true);w.setUint16(4,20,true);w.setUint16(6,20,true);w.setUint16(8,0x800,true);w.setUint32(16,crc,true);w.setUint32(20,data.length,true);w.setUint32(24,data.length,true);w.setUint16(28,name.length,true);w.setUint32(42,offset,true);c.set(name,46);central.push(c);offset+=h.length+data.length;}
const size=central.reduce((n,x)=>n+x.length,0);let [end,v]=bytes(22);v.setUint32(0,0x06054b50,true);v.setUint16(8,entries.length,true);v.setUint16(10,entries.length,true);v.setUint32(12,size,true);v.setUint32(16,offset,true);return new Blob([...local,...central,end],{type:'application/zip'});}
async function downloadSheets(){const b=$('downloadAll');b.disabled=true;try{notify('Preparando o ZIP com cinco folhas e dados de animação…');const entries=[];for(const action of Object.keys(E.ACTIONS)){const blob=await blobOf(makeSheet(action));entries.push({name:'guardian-'+action+'-registrado.png',data:new Uint8Array(await blob.arrayBuffer())});}entries.push({name:'animacoes.json',data:new TextEncoder().encode(JSON.stringify(registeredMetadata(),null,2))});saveBlob(zipStore(entries),'Mythos_Guardiao_Sprites_v1.0_Morte.zip');notify('ZIP pronto: cinco PNGs transparentes e animacoes.json.');}catch(e){notify(e.message);}finally{b.disabled=false;}}
function refreshSheet(){if(currentSheet===model.action)return;currentSheet=model.action;const d=GuardianData.atlas.sheets[currentSheet];const cell=d.cellExport||192;sheetCanvas.width=d.columns*cell;sheetCanvas.height=4*cell;renderer.sheet(sheetCanvas.getContext('2d'),currentSheet);$('sheetInfo').textContent=E.ACTIONS[currentSheet].label+' · '+d.columns+' colunas × 4 direções · '+(d.columns*4)+' quadros';}
function ground(){
const w=1000,h=600;ctx.clearRect(0,0,w,h);if(cfg.plain){ctx.fillStyle='#252e32';ctx.fillRect(0,0,w,h);ctx.fillStyle='#303b3f';ctx.fillRect(0,450,w,150);}else{
const g=ctx.createRadialGradient(470,260,30,500,310,670);g.addColorStop(0,'#5d7053');g.addColorStop(.55,'#344d42');g.addColorStop(1,'#142c2e');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
ctx.fillStyle='#9f927045';ctx.beginPath();ctx.ellipse(490,347,360,172,-.13,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ad9e7233';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(490,347,347,160,-.13,0,Math.PI*2);ctx.stroke();
for(let i=0;i<180;i++){const x=(i*137.83)%1000,y=(i*79.31)%600;ctx.strokeStyle=i%3?'#73907228':'#b9b47924';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y-6);ctx.moveTo(x,y);ctx.lineTo(x+4,y-8);ctx.stroke();}
for(let i=0;i<14;i++){const x=62+i*73,y=i%2?43:554;ctx.fillStyle='#192c2c';ctx.beginPath();ctx.ellipse(x,y,22+(i%3)*8,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#495747';ctx.beginPath();ctx.moveTo(x-15,y-2);ctx.lineTo(x-8,y-13);ctx.lineTo(x+9,y-15);ctx.lineTo(x+17,y-3);ctx.closePath();ctx.fill();ctx.strokeStyle='#7a816355';ctx.stroke();}
// Framing foliage kept away from the playable centre.
for(const [x,y,r] of [[0,0,105],[1030,20,145],[15,570,72],[990,585,95]]){ctx.fillStyle='#10282adb';ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#24463caa';ctx.beginPath();ctx.arc(x+15,y+8,r*.74,0,Math.PI*2);ctx.fill();}
}
if(cfg.grid){ctx.strokeStyle='#a5b49b25';ctx.lineWidth=1;for(let x=0;x<1000;x+=50){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,600);ctx.stroke();}for(let y=0;y<600;y+=50){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1000,y);ctx.stroke();}}
ctx.font='13px Georgia';ctx.textAlign='left';ctx.fillStyle='#ded6bb95';ctx.fillText('CLAREIRA DE TREINO',31,35);ctx.font='12px Arial';ctx.fillText('Teste isolado do personagem',31,55);
}
function shadow(x,y,size=1){ctx.save();ctx.fillStyle='#09151266';ctx.beginPath();ctx.ellipse(x,y+2,27*size,10*size,0,0,Math.PI*2);ctx.fill();ctx.restore();}
function drawDummy(){const wobble=Math.sin(dummy.shake*45)*dummy.shake*4;shadow(dummy.x,dummy.y,1);ctx.save();ctx.translate(dummy.x+wobble,dummy.y);ctx.strokeStyle='#382b1d';ctx.lineWidth=15;ctx.beginPath();ctx.moveTo(-28,0);ctx.lineTo(28,0);ctx.stroke();ctx.fillStyle='#795936';ctx.fillRect(-7,-109,14,108);ctx.strokeStyle='#402e1e';ctx.lineWidth=3;ctx.strokeRect(-7,-109,14,108);ctx.fillStyle='#b49a66';ctx.beginPath();ctx.ellipse(0,-71,23,30,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle='#7b4c37';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,-71,14,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#65502f';ctx.lineWidth=10;ctx.beginPath();ctx.moveTo(-39,-90);ctx.lineTo(39,-90);ctx.stroke();ctx.fillStyle='#aa8c59';ctx.beginPath();ctx.arc(0,-119,13,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#6e522f';ctx.lineWidth=2;ctx.stroke();ctx.restore();ctx.fillStyle='#d4cab0';ctx.font='13px Georgia';ctx.textAlign='center';ctx.fillText('Boneco de treino',dummy.x,dummy.y+27);}
function applyEvent(event){if(event.type!=='hit')return;const v={south:[0,1],north:[0,-1],west:[-1,0],east:[1,0]}[event.dir],dx=dummy.x-event.x,dy=dummy.y-event.y,dist=Math.hypot(dx,dy);if(dist<135&&(dist<1||(dx*v[0]+dy*v[1])/dist>.45)){hitCount++;dummy.shake=.6;effects.push({x:dummy.x,y:dummy.y-70,age:0});$('hits').textContent='Boneco de treino: '+hitCount+' acertos';}}
function render(){if(!renderer)return;ctx.save();ctx.setTransform(canvas.width/1000,0,0,canvas.height/600,0,0);ground();const drawHero=()=>{shadow(model.x,model.y,cfg.zoom*(model.action==='death'?1+.7*model.frame()/5:1));renderer.draw(ctx,model,model.x,model.y,cfg.zoom,{hair:cfg.hair,bounds:cfg.bounds});ctx.textAlign='center';ctx.font='13px Georgia';ctx.fillStyle='#f1dcaa';ctx.fillText(model.lifeState==='dead'?'Guardião · morto':'Guardião',model.x,model.y+27);};if(model.y<dummy.y){drawHero();drawDummy();}else{drawDummy();drawHero();}
for(const f of effects){ctx.strokeStyle='rgba(242,204,122,'+Math.max(0,1-f.age*2.5)+')';ctx.lineWidth=3;for(let j=0;j<7;j++){const a=j*Math.PI*2/7,r=8+f.age*65;ctx.beginPath();ctx.moveTo(f.x+Math.cos(a)*r,f.y+Math.sin(a)*r);ctx.lineTo(f.x+Math.cos(a)*(r+8),f.y+Math.sin(a)*(r+8));ctx.stroke();}}
ctx.restore();refreshSheet();$('dieBtn').disabled=model.lifeState!=='alive';$('reviveBtn').disabled=model.lifeState==='alive';$('attackBtn').disabled=model.lifeState!=='alive';$('state').textContent=(model.lifeState==='dead'?'Morto':E.ACTIONS[model.action].label)+' · '+names[model.dir]+(model.paused?' · Pausado':'');$('frameInfo').textContent='Quadro '+(model.frame()+1)+' / '+E.ACTIONS[model.action].frames+' · '+(model.action==='idle'?'Piscada a cada 3,8 s':E.ACTIONS[model.action].fps+' quadros/s');$('play').textContent=model.paused?'Continuar':'Pausar';for(const b of document.querySelectorAll('[data-dir]'))b.setAttribute('aria-pressed',String(b.dataset.dir===model.dir));}
function loop(now){const dt=last?Math.min((now-last)/1000,.05):0;last=now;if(held&&model.attackTime<=0&&!model.paused)attack(model.dir);for(const event of model.update(dt,{width:1000,height:600,minY:140*cfg.zoom+20,marginX:75*cfg.zoom}))applyEvent(event);if(!model.paused){dummy.shake=Math.max(0,dummy.shake-dt);for(const f of effects)f.age+=dt;effects=effects.filter(f=>f.age<.4);}render();raf=requestAnimationFrame(loop);}
function fit(){const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(1000*dpr);canvas.height=Math.round(600*dpr);render();}
function editable(target){return target&&(/INPUT|SELECT|TEXTAREA|BUTTON|A/.test(target.tagName)||target.isContentEditable);}
$('action').addEventListener('change',e=>selectAction(e.target.value));for(const b of document.querySelectorAll('[data-dir]'))b.addEventListener('click',()=>model.setDirection(b.dataset.dir));
$('zoom').addEventListener('input',e=>{cfg.zoom=Number(e.target.value);model.y=Math.max(model.y,140*cfg.zoom+20);model.x=Math.max(75*cfg.zoom,Math.min(1000-75*cfg.zoom,model.x));$('zoomValue').textContent=cfg.zoom.toLocaleString('pt-BR')+'×';});$('speed').addEventListener('input',e=>{model.speed=Number(e.target.value);$('speedValue').textContent=model.speed.toLocaleString('pt-BR')+'×';});
$('blink').addEventListener('change',e=>model.blink=e.target.checked);for(const id of ['hair','grid','bounds','plain'])$(id).addEventListener('change',e=>cfg[id]=e.target.checked);
$('play').addEventListener('click',()=>{model.paused=!model.paused;model.stepping=false;});$('step').addEventListener('click',()=>{held=false;model.step();render();});$('center').addEventListener('click',()=>{model.reset();$('action').value='auto';held=false;currentSheet='';render();});$('attackBtn').addEventListener('click',()=>attack());function die(){held=false;if(model.die()){$('action').value='death';currentSheet='';notify('Morte em execução; o último quadro permanece até reviver.');render();}}function revive(){held=false;if(model.revive()){$('action').value='auto';currentSheet='';notify('Personagem revivido no mesmo local.');render();}}$('dieBtn').addEventListener('click',die);$('reviveBtn').addEventListener('click',revive);$('touchAttack').addEventListener('click',()=>attack());
window.addEventListener('keydown',e=>{if(editable(e.target))return;const key=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright','shift',' ','p','home','k','v'].includes(key))e.preventDefault();if(key==='k'&&!e.repeat){die();return;}if(key==='v'&&!e.repeat){revive();return;}if(key===' '){if(!e.repeat)attack();return;}if(key==='p'&&!e.repeat){model.paused=!model.paused;model.stepping=false;return;}if(key==='home'){model.reset();$('action').value='auto';return;}if(model.lifeState==='alive')model.keys.add(key);});window.addEventListener('keyup',e=>model.keys.delete(e.key.toLowerCase()));
function release(){model.keys.clear();held=false;}
window.addEventListener('blur',release);document.addEventListener('visibilitychange',()=>{if(document.hidden)release();last=0;});window.addEventListener('resize',fit);
function pointerDir(e){const box=canvas.getBoundingClientRect(),x=(e.clientX-box.left)*1000/box.width,y=(e.clientY-box.top)*600/box.height;return E.facing(x-model.x,y-model.y,model.dir);}
canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;canvas.focus();e.preventDefault();if(model.lifeState!=='alive')return;held=true;model.dir=pointerDir(e);attack(model.dir);canvas.setPointerCapture?.(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(held&&model.attackTime<=0)model.dir=pointerDir(e);});window.addEventListener('pointerup',()=>held=false);window.addEventListener('pointercancel',release);canvas.addEventListener('contextmenu',e=>e.preventDefault());
for(const b of document.querySelectorAll('[data-key]')){b.addEventListener('pointerdown',e=>{e.preventDefault();if(model.lifeState==='alive')model.keys.add(b.dataset.key);b.setPointerCapture?.(e.pointerId);});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>model.keys.delete(b.dataset.key));}
$('touchRun').addEventListener('click',e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));on?model.keys.add('shift'):model.keys.delete('shift');});
$('downloadSheet').addEventListener('click',async()=>{try{const action=model.action;saveBlob(await blobOf(makeSheet(action)),'guardian-'+action+'-registrado.png');notify('Folha transparente exportada.');}catch(e){notify(e.message);}});$('downloadAll').addEventListener('click',downloadSheets);$('downloadMeta').addEventListener('click',()=>saveBlob(new Blob([JSON.stringify(registeredMetadata(),null,2)],{type:'application/json'}),'animacoes.json'));
$('snapshot').addEventListener('click',async()=>{try{const out=document.createElement('canvas');out.width=512;out.height=512;renderer.draw(out.getContext('2d'),model,256,470,3,{hair:cfg.hair});saveBlob(await blobOf(out),'guardian-pose-'+model.action+'.png');notify('Pose exportada com fundo transparente.');}catch(e){notify(e.message);}});
const ready=Promise.all(Object.entries(GuardianData.images).map(([name,src])=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve([name,im]);im.onerror=()=>reject(Error('Falha ao carregar '+name+'. Baixe novamente o HTML completo.'));im.src=src;}))).then(list=>{renderer=new GuardianRenderer(Object.fromEntries(list),GuardianData.atlas);$('loading').hidden=true;fit();raf=requestAnimationFrame(loop);return true;}).catch(e=>{$('loading').textContent=e.message;$('loading').classList.add('error');throw e;});
window.GuardianLab={model,cfg,ready,render,makeSheet,registeredMetadata,zipStore,crc32,applyEvent,get renderer(){return renderer;},get hits(){return hitCount;},stop(){cancelAnimationFrame(raf);}};
})();
